    for data in products_data:
        product = Product(
            name=data['name'],
            description=data['desc'],
            price=data['price'],
            stock=data['stock'],
            image=data.get('image', 'default_product.png'),
            seller_id=data['seller'].id,
            category_id=data['cat'],
            created_at=datetime.utcnow(),
            is_active=True
        )
        db.session.add(product)
        db.session.flush()

        for char_name, char_value in data.get('chars', {}).items():
            db.session.add(ProductCharacteristic(
                product_id=product.id,
                name=char_name,
                value=char_value
            ))

        print(f"  + {product.name}")

    db.session.commit()
    print(f"\nSeeded {len(products_data)} products successfully!")
